mapper.sql:
(
    q.chapter_text = #{segmentName}
    or q.chapter_text ilike (#{segmentName} || ' > %')
    or q.chapter_text ilike ('% > ' || #{segmentName})
    or q.chapter_text ilike ('% > ' || #{segmentName} || ' > %')
)

select.where:
q.del_flag = '0'
and q.subject_id = #{subjectId}
and q.textbook_id = #{textbookId}

    and (
        q.chapter_id in

            #{cid}


            or

                (
                    q.chapter_text = #{cname}
                    or q.chapter_text ilike (#{cname} || ' > %')
                    or q.chapter_text ilike ('% > ' || #{cname})
                    or q.chapter_text ilike ('% > ' || #{cname} || ' > %')
                )


    )


    and q.chapter_id = #{chapterId}


    and (
        q.chapter_text = #{chapterText}
        or q.chapter_text ilike (#{chapterText} || ' > %')
        or q.chapter_text ilike ('% > ' || #{chapterText})
        or q.chapter_text ilike ('% > ' || #{chapterText} || ' > %')
    )


    and q.knowledge_points::text ilike ('%' || #{knowledgePoint} || '%')

and q.difficulty >= #{difficultyMin}
and q.difficulty <= #{difficultyMax}
and q.question_type = #{questionType}
and q.source_type = #{sourceType}
and q.status = #{status}

    and q.content ilike ('%' || #{keyword} || '%')


    and q.create_time >= to_timestamp(#{params.beginTime}, 'YYYY-MM-DD HH24:MI:SS')


    and q.create_time <= to_timestamp(#{params.endTime}, 'YYYY-MM-DD HH24:MI:SS')

mapper.update:
update edu_qb_question set del_flag = '2', update_time = CURRENT_TIMESTAMP
where question_id in

    #{questionId}

mapper.select:
select q.chapter_id as "chapterId", elem as "tagName", count(*)::int as "useCount" from edu_qb_question q cross join lateral jsonb_array_elements_text( case when q.knowledge_points is null then '[]'::jsonb else q.knowledge_points end ) as elem where q.del_flag = '0' and q.status = '0' and q.chapter_id is not null and trim(elem) != '' and q.subject_id = #{subjectId} and q.textbook_id = #{textbookId}
and elem ilike ('%' || #{keyword} || '%')
group by q.chapter_id, elem order by elem

mapper.update:
update edu_qb_knowledge_tag
set use_count = greatest(use_count - 1, 0)
where subject_id = #{subjectId} and tag_name = #{tagName}

mapper.select:
select count(*)
from edu_qb_question
where del_flag = '0' and status = #{status}


where q.del_flag = '0' and q.status = '0'
  and q.subject_id = #{subjectId}
  and q.content_hash = #{contentHash}

  and q.question_id != #{excludeQuestionId}

order by q.create_time desc
limit 20


where q.del_flag = '0' and q.status = '0'
  and q.subject_id = #{subjectId}

  and q.question_id != #{excludeQuestionId}

order by q.create_time desc
limit #{limit}
